// ========== Learning Game Engine ==========
// 智学空间 - 学习游戏引擎（扩展版）

let currentGame = null;

function openLearningGameModal() {
    currentGame = null;
    var panel = document.getElementById("aiLogPanel");
    if (panel) panel.style.display = "block";
    resetGameModal();
    var modal = document.getElementById("learningGameModal");
    if (modal) { modal.style.display = "flex"; modal.classList.add("active"); }
}

function getDailyChallengeInfo() {
    try {
        var saved = JSON.parse(localStorage.getItem("dailyChallenge") || "{}");
        var today = new Date().toISOString().slice(0, 10);
        var streak = saved.streak || 0;
        var lastDate = saved.lastDate || "";
        var yesterday = new Date(Date.now() - 86400000).toISOString().slice(0, 10);
        if (lastDate !== today && lastDate !== yesterday) streak = 0;
        var completed = saved.lastDate === today && saved.completed;
        var gameTypes = ["wordchain","quickmath","idiom","riddle","scramble","typing","quiz_battle","idiom_chain","sudoku","logic"];
        var seed = 0;
        for (var i = 0; i < today.length; i++) seed += today.charCodeAt(i);
        var gameType = gameTypes[seed % gameTypes.length];
        var descs = { wordchain:"今日词语接龙挑战", quickmath:"今日速算挑战", idiom:"今日成语挑战", riddle:"今日猜谜挑战", scramble:"今日拼写挑战", typing:"今日打字挑战", quiz_battle:"今日知识问答挑战", idiom_chain:"今日成语接龙挑战", sudoku:"今日数独挑战", logic:"今日逻辑推理挑战" };
        return { available: !completed, desc: descs[gameType]||"每日挑战", streak: streak, gameType: gameType, date: today };
    } catch(e) { return { available: true, desc: "每日挑战", streak: 0, gameType: "quickmath", date: "" }; }
}

function updateDailyChallengeStreak() {
    try {
        var saved = JSON.parse(localStorage.getItem("dailyChallenge") || "{}");
        var today = new Date().toISOString().slice(0, 10);
        var yesterday = new Date(Date.now() - 86400000).toISOString().slice(0, 10);
        if (saved.lastDate === yesterday) { saved.streak = (saved.streak||0)+1; }
        else if (saved.lastDate !== today) { saved.streak = 1; }
        saved.lastDate = today;
        saved.completed = true;
        localStorage.setItem("dailyChallenge", JSON.stringify(saved));
    } catch(e) {}
}

