function handleGameInput(text) {
    if (!currentGame) return null;
    var input = text.trim();
    if (!input) return null;
    if (input === "退出游戏" || input === "结束游戏") { var result = endGame(true); currentGame = null; return result; }
    if (currentGame.type === "idiom_chain" && !currentGame.waitingStart && input === "提示") { return getIdiomChainHint(); }
    if (currentGame.waitingStart) { currentGame.waitingStart = false; currentGame.round = 1; return nextRound(); }
    var isCorrect = checkGameAnswer(input);
    if (isCorrect) {
        var roundScore = 10;
        var extraInfo = "";
        if (currentGame.type === "typing") {
            var elapsed = (Date.now() - currentGame.data.startTime) / 1000;
            var target = currentGame.data.target;
            var isChinese = /[\u4e00-\u9fa5]/.test(target);
            var charCount = target.length;
            var speed, speedUnit;
            if (isChinese) { speed = Math.round((charCount / elapsed) * 60); speedUnit = "字/分钟"; }
            else { var wordCount = target.split(/\s+/).length; speed = Math.round((wordCount / elapsed) * 60); speedUnit = "词/分钟"; }
            var correctChars = 0;
            var maxLen = Math.max(input.length, target.length);
            for (var i = 0; i < Math.min(input.length, target.length); i++) { if (input[i] === target[i]) correctChars++; }
            var accuracy = Math.round((correctChars / maxLen) * 100);
            currentGame.data.totalAccuracy = (currentGame.data.totalAccuracy || 0) + accuracy;
            currentGame.data.accuracyCount = (currentGame.data.accuracyCount || 0) + 1;
            roundScore = Math.max(5, Math.round(10 * (accuracy / 100)));
            extraInfo = "\n\u2328\uFE0F 速度：" + speed + " " + speedUnit + " | 准确率：" + accuracy + "%";
        }
        if (currentGame.type === "quiz_battle") {
            currentGame.data.streak = (currentGame.data.streak || 0) + 1;
            if (currentGame.data.streak >= 5) { roundScore = 20; extraInfo = "\n\u{1F525}\u{1F525} 超级连击" + currentGame.data.streak + "题！额外+10分！"; }
            else if (currentGame.data.streak >= 3) { roundScore = 15; extraInfo = "\n\u{1F525} 连续答对" + currentGame.data.streak + "题！额外+5分！"; }
            if (currentGame.data.timer) { clearInterval(currentGame.data.timer); currentGame.data.timer = null; }
        }
        if (currentGame.type === "idiom_chain") {
            currentGame.data.chainLength = (currentGame.data.chainLength || 0) + 1;
            roundScore = 10 + (currentGame.data.chainLength >= 3 ? 5 : 0) + (currentGame.data.chainLength >= 5 ? 5 : 0);
            extraInfo = "\n\u{1F409} 接龙链长：" + currentGame.data.chainLength;
            if (currentGame.data.timer) { clearInterval(currentGame.data.timer); currentGame.data.timer = null; }
        }
        if (currentGame.type === "sudoku") {
            roundScore = 20;
            extraInfo = "\n\u{1F9E9} 数独完成！";
        }
        if (currentGame.data.isDailyChallenge) { roundScore = 15; extraInfo += "\n\u{1F31F} 每日挑战额外+5分！"; }
        currentGame.score += roundScore;
        currentGame.round++;
        if (currentGame.round > currentGame.maxRounds) {
            var summaryInfo = "";
            if (currentGame.type === "typing" && currentGame.data.accuracyCount) { summaryInfo = "\n\n\u{1F4CA} 平均准确率：" + Math.round(currentGame.data.totalAccuracy / currentGame.data.accuracyCount) + "%"; }
            if (currentGame.type === "idiom_chain") { summaryInfo = "\n\n\u{1F409} 最终接龙链长：" + (currentGame.data.chainLength || 0); }
            if (currentGame.data.isDailyChallenge) { updateDailyChallengeStreak(); }
            var result = endGame(false) + summaryInfo;
            currentGame = null;
            return result;
        }
        var nextInfo = "";
        if (currentGame.type === "wordchain") { nextInfo = "\n你的词语「**" + input + "**」接龙成功！"; }
        if (currentGame.type === "idiom_chain") { nextInfo = "\n你的成语「**" + input + "**」接龙成功！"; }
        return "\u2705 **正确！+" + roundScore + "分**（当前得分：" + currentGame.score + "）" + extraInfo + nextInfo + "\n\n" + nextRound();
    } else {
        var wrongEntry = { question: currentGame.data.currentQuestion || "第" + currentGame.round + "轮", userAnswer: input, correctAnswer: currentGame.data.answer || currentGame.data.full || "未知" };
        currentGame.wrongAnswers.push(wrongEntry);
        if (currentGame.type === "quiz_battle") { currentGame.data.streak = 0; if (currentGame.data.timer) { clearInterval(currentGame.data.timer); currentGame.data.timer = null; } }
        if (currentGame.type === "idiom_chain") { if (currentGame.data.timer) { clearInterval(currentGame.data.timer); currentGame.data.timer = null; } }
        currentGame.round++;
        if (currentGame.round > currentGame.maxRounds) {
            var summaryInfo2 = "";
            if (currentGame.type === "typing" && currentGame.data.accuracyCount) { summaryInfo2 = "\n\n\u{1F4CA} 平均准确率：" + Math.round(currentGame.data.totalAccuracy / currentGame.data.accuracyCount) + "%"; }
            if (currentGame.type === "idiom_chain") { summaryInfo2 = "\n\n\u{1F409} 最终接龙链长：" + (currentGame.data.chainLength || 0); }
            if (currentGame.data.isDailyChallenge) { updateDailyChallengeStreak(); }
            var result2 = endGame(false) + summaryInfo2;
            currentGame = null;
            return result2;
        }
        var invalidInfo = "";
        if (currentGame.data.invalidHint) { invalidInfo = "\n" + currentGame.data.invalidHint; currentGame.data.invalidHint = ""; }
        return "\u274C **不对哦~**（当前得分：" + currentGame.score + "）" + invalidInfo + "\n\n" + nextRound();
    }
}

function nextRound() {
    var round = currentGame.round;
    switch (currentGame.type) {
        case "wordchain": return nextWordChain(round);
        case "quickmath": return nextQuickMath(round);
        case "memory": return nextMemory(round);
        case "idiom": return nextIdiom(round);
        case "idiom_chain": return nextIdiomChain(round);
        case "riddle": return nextRiddle(round);
        case "scramble": return nextScramble(round);
        case "typing": return nextTyping(round);
        case "quiz_battle": return nextQuizBattle(round);
        case "sudoku": return nextSudoku(round);
        case "logic": return nextLogic(round);
        case "math24": return nextMath24(round);
        case "geo_quiz": return nextGeoQuiz(round);
        case "poetry": case "feihua": return nextFeihua(round);
        case "chem_eq": case "chem_balance": return nextChemBalance(round);
        case "en_grammar": case "grammar": return nextGrammar(round);
        case "timeline": case "history_line": return nextHistoryLine(round);
        default: return "游戏类型错误。";
    }
}

function checkGameAnswer(input) {
    switch (currentGame.type) {
        case "wordchain": return checkWordChain(input);
        case "quickmath": return checkQuickMath(input);
        case "memory": return checkMemory(input);
        case "idiom": return checkIdiom(input);
        case "idiom_chain": return checkIdiomChain(input);
        case "riddle": return checkRiddle(input);
        case "scramble": return checkScramble(input);
        case "typing": return checkTyping(input);
        case "quiz_battle": return checkQuizBattle(input);
        case "sudoku": return checkSudoku(input);
        case "logic": return checkLogic(input);
        case "math24": return checkMath24(input);
        case "geo_quiz": return checkGeoQuiz(input);
        case "poetry": case "feihua": return checkFeihua(input);
        case "chem_eq": case "chem_balance": return checkChemBalance(input);
        case "en_grammar": case "grammar": return checkGrammar(input);
        case "timeline": case "history_line": return checkHistoryLine(input);
        default: return false;
    }
}

function endGame(early) {
    var score = currentGame ? currentGame.score : 0;
    var rounds = currentGame ? currentGame.round - 1 : 0;
    var wrongAnswers = currentGame ? currentGame.wrongAnswers : [];
    var grade = "";
    if (score >= 90) grade = "\u{1F3C6} 太厉害了！你是学习天才！";
    else if (score >= 70) grade = "\u{1F31F} 非常棒！继续保持！";
    else if (score >= 50) grade = "\u{1F44D} 不错！还有进步空间！";
    else if (score >= 30) grade = "\u{1F4AA} 加油！多练习就能提高！";
    else grade = "\u{1F4DA} 别灰心，多复习再来挑战吧！";

    // Award XP for completing a game
    if (typeof LevelSystem !== 'undefined') {
        LevelSystem.addXP('gamePlay', LevelSystem.xpRewards.gamePlay, '完成游戏');
        // Award bonus XP for winning (score >= 70)
        if (score >= 70) {
            LevelSystem.addXP('gameWin', LevelSystem.xpRewards.gameWin, '游戏获胜');
        }
    }

    if (wrongAnswers.length > 0 && typeof state !== "undefined" && state.currentSubject) {
        wrongAnswers.forEach(function(w) { if (typeof addErrorToBook === "function") { addErrorToBook(state.currentSubject, w.question, w.userAnswer, w.correctAnswer, "游戏中的错题"); } });
    }
    var wrongSection = "";
    if (wrongAnswers.length > 0) {
        wrongSection = "\n\n\u274C **本轮错误：\n" + wrongAnswers.map(function(w, i) { return (i+1) + ". " + w.question + "\n   你的回答：" + w.userAnswer + "\n   正确答案：" + w.correctAnswer; }).join("\n") + "\n\n\u{1F4A1} 错误题目已自动加入错题本";
    }
    return "\u{1F3AE} **游戏结束" + (early ? "（中途退出）" : "") + "**\n\n<div class=\"game-result\">\n<div class=\"result-score\">" + score + "</div>\n<div class=\"result-label\">总分（共" + rounds + "轮，每轮10分）</div>\n</div>\n\n" + grade + wrongSection + "\n\n\u{1F4A1} 点击「\u{1F3AE} 学习游戏」按钮再来一局！";
}



