// WordChain
var lastWordChain = "";
function nextWordChain(round) {
    var w = wordChainPool[Math.floor(Math.random() * wordChainPool.length)];
    lastWordChain = w;
    currentGame.data.push({ q: "请用一个以 \"" + w.charAt(w.length - 1) + "\" 字开头的双字词语", a: "(任意正确词语)" });
    return "<div>请用一个以 <strong>\"" + w.charAt(w.length - 1) + "\"</strong> 字开头的双字词语</div><div style='color:var(--text-muted);font-size:12px;margin-top:4px;'>上一个词: " + w + "</div>";
}
function checkWordChain(input) {
    if (!lastWordChain) return false;
    var lastChar = lastWordChain.charAt(lastWordChain.length - 1);
    return input.length >= 2 && input.charAt(0) === lastChar;
}

// QuickMath
var lastQuickMath = { q: "", a: "" };
function nextQuickMath(round) {
    var ops = ['+', '-', '*'];
    var op = ops[Math.floor(Math.random() * ops.length)];
    var a = Math.floor(Math.random() * 20) + 1;
    var b = Math.floor(Math.random() * 20) + 1;
    if (op === '-' && a < b) { var t = a; a = b; b = t; }
    var q = a + " " + op + " " + b + " = ?";
    var ans = op === '+' ? a + b : (op === '-' ? a - b : a * b);
    lastQuickMath = { q: q, a: String(ans) };
    currentGame.data.push({ q: q, a: String(ans) });
    return "<div>" + q + "</div>";
}
function checkQuickMath(input) { return input === lastQuickMath.a; }

// Memory
var lastMemory = "";
function nextMemory(round) {
    var items = ['🍎','🍊','🍇','🍌','🍓','🍉','🍒','🍑'];
    var selected = [];
    while (selected.length < 4) {
        var item = items[Math.floor(Math.random() * items.length)];
        if (selected.indexOf(item) === -1) selected.push(item);
    }
    var cards = selected.concat(selected);
    for (var i = cards.length - 1; i > 0; i--) {
        var j = Math.floor(Math.random() * (i + 1));
        var t = cards[i]; cards[i] = cards[j]; cards[j] = t;
    }
    lastMemory = cards.join(',');
    currentGame.data.push({ q: "记住这些卡片的位置", a: lastMemory });
    var html = "<div>记住这些卡片的位置（5秒后消失）：</div><div style='display:grid;grid-template-columns:repeat(4,1fr);gap:8px;margin-top:10px;'>";
    for (var i = 0; i < cards.length; i++) {
        html += "<div style='background:var(--bg-card);border:1px solid var(--border);border-radius:8px;padding:16px;text-align:center;font-size:24px;' data-card='" + i + "'>" + cards[i] + "</div>";
    }
    html += "</div>";
    setTimeout(function() {
        var els = document.querySelectorAll('[data-card]');
        for (var i = 0; i < els.length; i++) els[i].textContent = '❓';
    }, 5000);
    return html;
}
function checkMemory(input) { return true; }

