// Sudoku
var lastSudoku = { board: [], solution: [], size: 4 };
function nextSudoku(round) {
    var size = round === 3 ? 9 : 4;
    var board = generateSudoku(size);
    lastSudoku = board;
    currentGame.data.push({ q: "完成数独", a: "(填入空格)" });
    var html = "<div>请填入空格完成" + size + "x" + size + "数独（每行每列每宫不重复）：</div><div style='margin-top:10px;font-family:monospace;font-size:16px;line-height:1.8;'>";
    for (var i = 0; i < size; i++) {
        for (var j = 0; j < size; j++) {
            var val = board.board[i][j];
            if (val === 0) html += "<span style='color:var(--primary);font-weight:bold;'> _ </span>";
            else html += " " + val + " ";
            if (j < size - 1) html += "|";
        }
        html += "<br>";
        if (i < size - 1) {
            for (var k = 0; k < size; k++) html += "---" + (k < size - 1 ? "+" : "");
            html += "<br>";
        }
    }
    html += "</div><div style='color:var(--text-muted);font-size:12px;margin-top:8px;'>输入格式：按行依次输入所有数字，空格用0代替</div>";
    return html;
}
function generateSudoku(size) {
    var solution = [];
    for (var i = 0; i < size; i++) {
        solution[i] = [];
        for (var j = 0; j < size; j++) {
            if (size === 4) solution[i][j] = (i + j) % 4 + 1;
            else solution[i][j] = (i * 3 + Math.floor(i / 3) + j) % 9 + 1;
        }
    }
    var board = [];
    for (var i = 0; i < size; i++) {
        board[i] = [];
        for (var j = 0; j < size; j++) {
            board[i][j] = Math.random() > 0.5 ? solution[i][j] : 0;
        }
    }
    return { board: board, solution: solution, size: size };
}
function checkSudoku(input) {
    var nums = input.replace(/\s/g, '').split('');
    var size = lastSudoku.size;
    if (nums.length !== size * size) return false;
    for (var i = 0; i < size; i++) {
        for (var j = 0; j < size; j++) {
            var idx = i * size + j;
            if (parseInt(nums[idx]) !== lastSudoku.solution[i][j]) return false;
        }
    }
    return true;
}

