// Math24 (24点)
var lastMath24 = { nums: [], answer: 24 };
function nextMath24(round) {
    var nums = [];
    for (var i = 0; i < 4; i++) nums.push(Math.floor(Math.random() * 13) + 1);
    lastMath24.nums = nums;
    currentGame.data.push({ q: "24点：" + nums.join(", "), a: "24" });
    return "<div>🎯 24点挑战</div><div style='font-size:20px;margin:10px 0;'>请用 <strong style='color:var(--primary);'>" + nums.join(", ") + "</strong> 通过加减乘除得到24</div><div style='color:var(--text-muted);font-size:12px;'>每个数字必须且只能使用一次，输入算式如：(3+5)*4-8</div>";
}
function checkMath24(input) {
    try {
        var expr = input.replace(/[^0-9+\-*/().\s]/g, '');
        var usedNums = lastMath24.nums.slice();
        var numMatches = expr.match(/\d+/g);
        if (!numMatches || numMatches.length !== 4) return false;
        for (var i = 0; i < numMatches.length; i++) {
            var n = parseInt(numMatches[i]);
            var idx = usedNums.indexOf(n);
            if (idx === -1) return false;
            usedNums.splice(idx, 1);
        }
        var result = Function('"use strict"; return (' + expr + ')')();
        return Math.abs(result - 24) < 0.0001;
    } catch (e) { return false; }
}

